#include <stdint.h>
#include <stdbool.h>
#include "stm32f4xx.h"
#include "sensors.h"
#include "flight_control.h"

// System clock configuration
void SystemClock_Config(void);

// Main application
int main(void) {
    // Initialize system clock
    SystemClock_Config();

    // Initialize all sensors
    if (!sensors_init()) {
        // Sensor initialization failed - flash LED or enter safe mode
        while (1) {
            // Error handler
        }
    }

    // Initialize flight control system
    flight_control_init();

    // Main control loop
    while (1) {
        // Read sensor data
        imu_data_t imu;
        baro_data_t baro;
        mag_data_t mag;
        gps_data_t gps;

        if (read_imu(&imu) && read_baro(&baro) && read_mag(&mag)) {
            read_gps(&gps); // GPS is optional for basic operation

            // Update flight state with sensor data
            flight_state_t state = {
                .acceleration_x = imu.accel_x,
                .acceleration_y = imu.accel_y,
                .acceleration_z = imu.accel_z,
                .gyro_x = imu.gyro_x,
                .gyro_y = imu.gyro_y,
                .gyro_z = imu.gyro_z,
                .pressure = baro.pressure,
                .altitude = baro.altitude,
                .heading = mag.heading,
                .latitude = gps.latitude,
                .longitude = gps.longitude,
                .gps_altitude = gps.altitude
            };

            // Execute flight control logic
            flight_control_update(&state);
        }

        // Small delay for sensor reading stability
        for (volatile int i = 0; i < 100000; i++);
    }
}

void SystemClock_Config(void) {
    // Enable HSE and PLL for 168MHz operation (STM32F4 typical)
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY));

    // Configure PLL
    RCC->PLLCFGR = (8 << RCC_PLLCFGR_PLLM_Pos) | 
                   (336 << RCC_PLLCFGR_PLLN_Pos) |
                   (0 << RCC_PLLCFGR_PLLP_Pos) |
                   (7 << RCC_PLLCFGR_PLLQ_Pos) |
                   RCC_PLLCFGR_PLLSRC_HSE;

    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    // Configure flash latency
    FLASH->ACR = FLASH_ACR_LATENCY_5WS | FLASH_ACR_ICEN | FLASH_ACR_DCEN | FLASH_ACR_PRFTEN;

    // Switch to PLL
    RCC->CFGR |= RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

    // Configure APB1 = 42MHz, APB2 = 84MHz
    RCC->CFGR |= RCC_CFGR_PPRE1_DIV4 | RCC_CFGR_PPRE2_DIV2;
}

